import Image from "next/image";
import Link from "next/link";
import type { ReactNode } from "react";
import type { ImageKey } from "@/lib/images";
import { getPhoto } from "@/lib/images";
import { PHONE_DISPLAY, PHONE_E164 } from "@/lib/pages";

type PageHeroProps = {
  kicker?: string;
  title: string;
  lead: ReactNode;
  ctaLabel?: string;
  secondaryHref?: string;
  secondaryLabel?: string;
  variant?: "home" | "page";
  imageKey?: ImageKey;
};

export function PageHero({
  kicker,
  title,
  lead,
  ctaLabel = "Call now",
  secondaryHref,
  secondaryLabel,
  variant = "page",
  imageKey = "hero-service",
}: PageHeroProps) {
  const photo = getPhoto(variant === "home" ? "hero-home" : imageKey);

  return (
    <section className={`beacon-hero beacon-hero--${variant}`}>
      <div className="beacon-hero__glow" aria-hidden="true" />
      <div className="beacon-hero__chevrons" aria-hidden="true" />
      <div className="beacon-hero__inner">
        <div className="beacon-hero__copy">
          {kicker && <p className="beacon-kicker">{kicker}</p>}
          <h1>{title}</h1>
          <div className="beacon-lead">{lead}</div>
          <div className="beacon-actions">
            <a className="btn btn-beacon" href={`tel:${PHONE_E164}`}>
              <span className="btn-label">{ctaLabel}</span>
              <span className="btn-value">{PHONE_DISPLAY}</span>
            </a>
            {secondaryHref && secondaryLabel && (
              <Link className="btn btn-outline-light" href={secondaryHref}>{secondaryLabel}</Link>
            )}
          </div>
          <ul className="beacon-stats" aria-label="Service highlights">
            <li><strong>24/7</strong> dispatch</li>
            <li><strong>Mobile</strong> to you</li>
            <li><strong>Canada</strong> wide</li>
          </ul>
        </div>
        <div className="beacon-hero__visual">
          <div className="beacon-frame">
            <Image
              src={photo.src}
              alt={photo.alt}
              fill
              priority
              sizes="(max-width: 900px) 100vw, 50vw"
              className="beacon-img"
            />
            <span className="beacon-frame__tag" aria-hidden="true">Live dispatch</span>
          </div>
          <p className="beacon-caption">{photo.caption}</p>
        </div>
      </div>
    </section>
  );
}
